import mujoco
# 4111 = 1 + 2 + 4 + 8 + 16 + 256 + 32 + 64 + 128 + 2048 + 1024 + 4096
# Let's check which bits are set
state = 4111
for attr in dir(mujoco.mjtState):
    if not attr.startswith('_') and attr.startswith('mjSTATE'):
        try:
            val = getattr(mujoco.mjtState, attr)
            if hasattr(val, 'value') and (state & val.value):
                print(f'{attr}: {val.value} (included)')
        except:
            pass
" 2>&1

